import {fetchRoad,estimateTrip} from './trip.mjs';
import {attachSearch} from './search.mjs';
import {DEFAULTS,NETWORKS,SAMPLE,payload,consumption,plan,legEnergy,validate} from './engine.mjs';
import {startMap,parseCoordinates,selectOnMap,updatePins,fitPins,showRoad} from './free-map.mjs';
import {exportTrip} from './export.mjs';
const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let settings={...structuredClone(DEFAULTS),origin:"",destination:""},route=structuredClone(SAMPLE),result=null,excluded=[],baseRoute=null,busy=false,planned=null,dirty=false;
try{const saved=JSON.parse(localStorage.getItem('atto-settings-v1'));if(saved)settings={...settings,...saved,mode:'sample',origin:"",destination:"",tariffs:{...DEFAULTS.tariffs,...saved.tariffs}};}catch{}
let liveRoad=null,liveKey="",requestId=0,roadController;
const selectedPlaces={};
const searches={};
const numeric=['battery','reserve','buffer','speed','people','personWeight','luggage','baseConsumption','headwind','temperature'];
function populate(){for(const k of [...numeric,'origin','destination','payloadOverride'])$(k).value=settings[k];$('fastOnly').checked=settings.fastOnly;renderNetworks();$('tariffs').innerHTML=NETWORKS.map(n=>`<label>${n} assumed price<div class="unit-input"><input id="price-${n}" type="number" min="0.1" max="100" step="0.1" value="${Number(settings.tariffs[n])}"><span>₺/kWh</span></div></label>`).join('');syncLabels();}
function read(){for(const k of numeric)settings[k]=Number($(k).value);for(const k of ['origin','destination','payloadOverride'])settings[k]=$(k).value.trim();settings.fastOnly=$('fastOnly').checked;for(const n of NETWORKS)settings.tariffs[n]=Number($('price-'+n).value);try{localStorage.setItem('atto-settings-v1',JSON.stringify(settings));}catch{}return settings;}
function syncLabels(){read();$('batteryValue').textContent=settings.battery;$('speedValue').textContent=settings.speed;$('payloadBadge').textContent=Math.round(payload(settings))+' kg';}
function renderNetworks(){$('networks').innerHTML=NETWORKS.map(n=>`<button type="button" data-network="${n}" aria-pressed="${settings.networks.includes(n)}" class="network ${settings.networks.includes(n)?'active':''}">${n}</button>`).join('');}
const time=m=>`${Math.floor(m/60)}h ${Math.round(m%60)}m`;const money=v=>Math.round(v).toLocaleString('tr-TR');
function mapsUrl(stop){const u=new URL('https://www.google.com/maps/dir/');u.searchParams.set('api','1');u.searchParams.set('destination',stop?(stop.location?`${stop.location.lat},${stop.location.lng}`:`${stop.network} ${stop.name} İzmir Yönü`):settings.destination);if(stop?.location)u.searchParams.set('destination_place_id',stop.id);u.searchParams.set('travelmode','driving');if(!stop)u.searchParams.set('origin',settings.origin);return u.href;}
function syncMap(focus=false){const points=[];for(const [id,label,title] of [['origin','A','Starting point'],['destination','B','Destination']]){const coord=selectedPlaces[id]?.label===$(id).value?selectedPlaces[id]:parseCoordinates($(id).value);if(coord)points.push({...coord,label,title});}if(result&&!dirty)result.stops.forEach((p,i)=>{if(p.location)points.push({...p.location,label:String(i+1),title:p.name});});updatePins(points,{focus});}
function openAddresses(){read();if(!settings.origin||!settings.destination){$('locationStatus').textContent='Enter a starting point and destination first.';return;}window.open(exportTrip(...['origin','destination'].map(id=>selectedPlaces[id]?.label===$(id).value?`${selectedPlaces[id].lat},${selectedPlaces[id].lng}`:settings[id]),[]).full,'_blank','noopener');}
async function initializeMap(){try{await startMap({onStatus:text=>$('mapStatus').textContent=text,onPick:(target,coord)=>{$(target).value=`${coord.lat.toFixed(6)}, ${coord.lng.toFixed(6)}`;syncLabels();invalidate();syncMap();$('locationStatus').textContent=`${target==='origin'?'Start':'Destination'} selected on the map. Open these points in Google Maps for a road route.`;document.querySelectorAll('[data-pick]').forEach(b=>b.setAttribute('aria-pressed','false'));}});syncMap();}catch{} }
function invalidate(){refreshLiveMetrics();dirty=true;$('notice').textContent='Choose your From and To points, then calculate your trip. Road distance and driving time come from OSRM; battery estimates use your vehicle settings.';syncMap();$('mapButton').disabled=true;$('exportRoute').disabled=true;$('exportStatus').textContent='Charging-stop export becomes available when a verified charging plan is connected.';}
function showExport(){if(!result||!planned||dirty)return;const trip=exportTrip(planned.origin,planned.destination,result.stops);$('exportSummary').textContent=`${planned.origin} → ${planned.destination} · ${trip.count} charging stops`;$('exportWarning').textContent=route.source==='sample'?'Sample itinerary: station locations and distances are not verified. Review the stop matches in Google Maps before driving.':'Your selected stops are sent in order. Google Maps may recalculate the roads; EV battery estimates and charging targets stay in EV Route.';$('fullRoute').hidden=!trip.full;if(trip.full){$('fullRoute').href=trip.full;$('fullRoute').textContent=`Open route with all ${trip.count} stops ↗`;}$('exportLimit').textContent=trip.full?(trip.count>3?'Google Maps mobile browsers may omit stops beyond three. If that happens, use the complete mobile-safe trip parts below.':'Your route fits Google Maps’ mobile-browser waypoint limit.'):'This trip exceeds a single Google Maps link’s limits. Use these trip parts in order; every stop is included.';$('tripParts').innerHTML=trip.parts.map((p,i)=>`<a class="trip-part" href="${esc(p.url)}" target="_blank" rel="noopener"><strong>Part ${i+1} ↗</strong><span>${esc(p.from)} → ${esc(p.to)}</span><small>${p.stopLabels.map(esc).join(' → ')}</small></a>`).join('');$('tripPartsDetails').open=!trip.full;$('tripPartsDetails').hidden=trip.parts.length===1&&!!trip.full;$('exportDialog').showModal();}
function chart(){let trace=[{km:0,soc:settings.battery}],prev=0,soc=settings.battery;for(const stop of [...result.stops,{km:route.distance}]){for(const p of route.profile.filter(p=>p.km>prev&&p.km<stop.km))trace.push({km:p.km,soc:soc-legEnergy(route,prev,p.km,settings).energy/settings.capacity*100});const arrival=soc-legEnergy(route,prev,stop.km,settings).energy/settings.capacity*100;trace.push({km:stop.km,soc:arrival});if(stop.target){soc=stop.target;trace.push({km:stop.km,soc});}prev=stop.km;}
const x=k=>40+k/route.distance*600,y=s=>115-s;const path=trace.map((p,i)=>`${i?'L':'M'}${x(p.km).toFixed(1)},${y(p.soc).toFixed(1)}`).join(' ');$('batteryChart').innerHTML=`<svg viewBox="0 0 660 145" role="img" aria-label="Estimated battery along the route, with reserve and charging stops"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b2d391" stop-opacity=".35"/><stop offset="1" stop-color="#b2d391" stop-opacity=".02"/></linearGradient></defs>${[25,50,75,100].map(s=>`<line x1="40" x2="640" y1="${y(s)}" y2="${y(s)}" stroke="#edf0e9"/><text x="3" y="${y(s)+3}" fill="#8a9585" font-size="9">${s}%</text>`).join('')}<path d="${path} L640,115 L40,115Z" fill="url(#fill)"/><line x1="40" x2="640" y1="${y(result.floor)}" y2="${y(result.floor)}" stroke="#bea267" stroke-dasharray="4 4"/><path d="${path}" stroke="#467751" stroke-width="2.5" fill="none"/>${result.stops.map((p,i)=>`<circle cx="${x(p.km)}" cy="${y(p.target)}" r="4" fill="#467751" stroke="#fff" stroke-width="2"/><text x="${x(p.km)}" y="135" text-anchor="middle" fill="#73826e" font-size="9">Stop ${i+1}</text>`).join('')}<text x="40" y="135" fill="#73826e" font-size="9">Start</text><text x="640" y="135" text-anchor="end" fill="#73826e" font-size="9">${Math.round(route.distance)} km</text></svg>`;}
function render(){planned={origin:settings.origin,destination:settings.destination};dirty=false;$('exportRoute').disabled=false;$('mapButton').disabled=false;$('exportStatus').textContent=`${result.stops.length} charging stops, in order · no API key needed`;syncMap();document.querySelectorAll('[data-priority]').forEach(b=>{b.classList.toggle('active',b.dataset.priority===settings.priority);b.setAttribute('aria-pressed',b.dataset.priority===settings.priority);});$('error').hidden=true;$('metrics').innerHTML=[['Journey estimate',time(result.driveMinutes+result.minutes),`${Math.round(route.distance)} km · driving + charging`],['Charging',`${result.stops.length} <small>stops</small>`,`${Math.round(result.minutes)} min incl. stop overhead`],['Charging estimate',`₺${money(result.cost)}`,'Your tariffs · excludes tolls'],['Arrival battery',`${Math.round(result.arrival)}<small>%</small>`,`${settings.reserve}% minimum + ${settings.buffer}% buffer`]].map((m,i)=>`<div class="metric ${i===3?'highlight':''}"><span class="metric-label">${m[0]}</span><strong>${m[1]}</strong><p>${m[2]}</p></div>`).join('');$('chartSubtitle').textContent=`${Math.round(result.payload)} kg payload · ${result.consumption.toFixed(1)} kWh/100 km on level road`;chart();$('stopCount').textContent=result.stops.length;$('stops').innerHTML=result.stops.map((p,i)=>`<article class="stop"><span class="stop-index">${i+1}</span><div><h3>${esc(p.name)}</h3><div class="stop-meta"><span class="network-tag">${esc(p.network)}</span><span>${p.power} kW ${p.power>=50?'DC':'AC'}</span><span>At ${Math.round(p.km)} km</span></div><div class="stop-battery">${Math.round(p.arrival)}% arrival → <strong>${p.target}% departure</strong> · +${p.kwh.toFixed(1)} kWh</div></div><div class="stop-actions"><strong>~${Math.round(p.minutes)} min · ₺${money(p.cost)}</strong><a href="${esc(mapsUrl(p))}" target="_blank" rel="noopener">Open stop ↗</a><button class="exclude" data-exclude="${esc(p.id)}">Exclude & recalculate</button></div></article>`).join('')+`<div class="destination-row"><span>◎ ${esc(settings.destination)}</span><strong>Arrive at ~${Math.round(result.arrival)}%</strong></div>`;$('restoreButton').hidden=!excluded.length;$('notice').textContent='Real map, illustrative charging plan. Sample distances, terrain and charger power are not verified. No live road routing or charger feed is connected.';syncMap();}

function error(e){invalidate();$('restoreButton').hidden=!excluded.length;$('error').textContent=e.message||String(e);$('error').hidden=false;result=null;$('metrics').innerHTML='';$('batteryChart').innerHTML='';$('stops').innerHTML='<p class="empty">No current plan. Adjust your inputs and calculate again.</p>';$('stopCount').textContent='—';$('chartSubtitle').textContent='';syncMap();}
async function calculate(refresh=false){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{read();validate(settings);if(!settings.origin||!settings.destination)throw Error('Enter both your starting point and destination.');if(settings.origin!==DEFAULTS.origin||settings.destination!==DEFAULTS.destination)throw Error('The free map is ready, but automatic charging plans for new routes are not connected yet. Use “Navigate these addresses” for Google Maps directions, Automatic charging-stop planning is still in development.');route=structuredClone(SAMPLE);result=plan(route,settings,excluded);render();}catch(e){error(e);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);$('mapButton').disabled=dirty||!result;$('exportRoute').disabled=dirty||!result;}}
$('tripForm').addEventListener('submit',e=>{e.preventDefault();calculateLiveTrip();if(innerWidth<760)$('notice').scrollIntoView({behavior:'smooth',block:'start'});});$('tripForm').addEventListener('input',()=>{syncLabels();invalidate();syncMap();if(result){$('notice').textContent='Settings changed. The results below reflect your previous calculation. Select “Find my charging stops” to update.';}});$('networks').addEventListener('click',e=>{const n=e.target.dataset.network;if(!n)return;settings.networks=settings.networks.includes(n)?settings.networks.filter(x=>x!==n):[...settings.networks,n];renderNetworks();invalidate();});document.querySelectorAll('[data-priority]').forEach(b=>b.addEventListener('click',()=>{settings.priority=b.dataset.priority;document.querySelectorAll('[data-priority]').forEach(x=>x.classList.toggle('active',x===b));read();}));$('stops').addEventListener('click',e=>{if(e.target.dataset.exclude){excluded.push(e.target.dataset.exclude);calculate();}});$('restoreButton').onclick=()=>{excluded=[];calculate(true);};$('mapButton').onclick=showExport;$('exportRoute').onclick=showExport;$('freeMapInfo').onclick=()=>$('mapInfoDialog').showModal();$('vehicleButton').onclick=()=>{$('modelDetails').open=true;$('modelDetails').scrollIntoView({behavior:'smooth',block:'center'});};$('resetButton').onclick=()=>{settings={...structuredClone(DEFAULTS),origin:"",destination:""};excluded=[];populate();invalidate();};$('locateButton').onclick=()=>{if(!navigator.geolocation){$('locationStatus').textContent='Location is unavailable. Enter an address or choose a point on the map.';return;}$('locateButton').disabled=true;$('locationStatus').textContent='Finding your current location…';navigator.geolocation.getCurrentPosition(p=>{$('locateButton').disabled=false;$('origin').value=`${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)}`;syncLabels();invalidate();syncMap(true);$('locationStatus').textContent=`Location found (accuracy about ${Math.round(p.coords.accuracy)} m). You can open these addresses in Google Maps.`;},e=>{$('locateButton').disabled=false;$('locationStatus').textContent=e.code===1?'Location permission was denied. Allow it in your browser settings, or choose a point on the map.':'Location could not be found. Enter an address or choose a point on the map.';},{enableHighAccuracy:true,timeout:12000,maximumAge:60000});};
$('navigateAddresses').onclick=openAddresses;
$('fitMap').onclick=fitPins;
$('retryMap').onclick=initializeMap;
document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{selectOnMap(b.dataset.pick);document.querySelectorAll('[data-pick]').forEach(x=>x.setAttribute('aria-pressed',x===b?'true':'false'));$('locationStatus').textContent=`Tap the map to choose your ${b.dataset.pick==='origin'?'starting point':'destination'}.`;});
for(const id of ['origin','destination']){searches[id]=attachSearch($(id),place=>{selectedPlaces[id]=place;syncLabels();invalidate();syncMap(true);});}
populate();invalidate();initializeMap();

function tripPoints(){return ['origin','destination'].map(id=>selectedPlaces[id]?.label===$(id).value?selectedPlaces[id]:parseCoordinates($(id).value));}
function pointKey(){const points=tripPoints();return points.every(Boolean)?JSON.stringify(points.map(p=>[p.lat,p.lng])):'';}
function clearLive(){ $('metrics').innerHTML='';$('batteryChart').innerHTML='';$('chartSubtitle').textContent='';showRoad(null); }
function refreshLiveMetrics(){
 const key=pointKey();
 if(liveRoad&&key===liveKey){try{renderLive();}catch(e){clearLive();$('tripStatus').textContent=e.message;}return;}
 if(roadController){roadController.abort();roadController=null;requestId++;}
 liveRoad=null;clearLive();$('tripStatus').textContent='Choose From and To, then select Calculate my trip. Select an address suggestion to locate it precisely.';
}
async function calculateLiveTrip(){
 read();const points=tripPoints();if(!points.every(Boolean)){ $('tripStatus').textContent='Select a suggestion for both addresses, use current location, or pick points on the map first.';return;}
 const key=pointKey();if(liveRoad&&key===liveKey){refreshLiveMetrics();return;}
 roadController?.abort();const controller=new AbortController();roadController=controller;const id=++requestId;clearLive();$('tripStatus').textContent='Calculating the road route…';const timeout=setTimeout(()=>controller.abort(),20000);
 try{const road=await fetchRoad(...points,{signal:controller.signal});if(id!==requestId||key!==pointKey())return;liveRoad=road;liveKey=key;read();renderLive();showRoad(road.geometry,{focus:true});}
 catch(e){if(id===requestId){liveRoad=null;clearLive();$('tripStatus').textContent=e.name==='AbortError'?'Routing timed out. Please try Calculate my trip again.':e.message;}}
 finally{clearTimeout(timeout);if(id===requestId)roadController=null;}
}
function renderLive(){
 const t=estimateTrip(liveRoad,settings);
 const arrival=t.arrival<0?'Not reachable':`${t.arrival.toFixed(0)}<small>%</small>`;
 const rows=[['Road distance',`${t.km.toFixed(0)} <small>km</small>`,'OSRM driving route'],['Driving time',time(t.minutes),'No live traffic or charging time'],['Estimated energy',`${t.energy.toFixed(1)} <small>kWh</small>`,`${t.rate.toFixed(1)} kWh/100 km · level-road model`],['Arrival without charging',arrival,t.arrival<0?`Battery would run out around ${t.rangeToEmpty.toFixed(0)} km`:`${t.floor}% reserve + buffer target`],['Distance until reserve',`${t.rangeToReserve.toFixed(0)} <small>km</small>`,`At your current ${settings.battery}% starting battery`],['Additional charge needed',`${t.chargingNeeded.toFixed(1)} <small>kWh</small>`,'Battery energy needed to finish at reserve + buffer']];
 $('metrics').innerHTML=rows.map(m=>`<div class="metric"><span class="metric-label">${m[0]}</span><strong>${m[1]}</strong><p>${m[2]}</p></div>`).join('');
 $('tripStatus').textContent=(t.chargingNeeded>0?`Charging required: add at least ${t.chargingNeeded.toFixed(1)} kWh to finish at ${t.floor}%. Plan a charging stop before approximately ${t.rangeToReserve.toFixed(0)} km. `:`Estimated arrival is above your ${t.floor}% target. `)+'Estimates exclude terrain. Verified charging stations, charging time and prices are not connected.';
 $('chartSubtitle').textContent=`Without charging · ${t.payload.toFixed(0)} kg payload · ${settings.speed} km/h consumption scenario across the trip. OSRM driving time uses its own road-speed model.`;
 const x=km=>40+Math.min(t.km,km)/t.km*600,y=soc=>120-Math.max(0,Math.min(100,soc));
 $('batteryChart').innerHTML=`<svg viewBox="0 0 680 160" role="img" aria-label="Estimated battery without charging, stopping at zero if the trip is not reachable"><line x1="40" x2="640" y1="${y(t.floor)}" y2="${y(t.floor)}" stroke="#b99548" stroke-dasharray="5 5"/><text x="45" y="${y(t.floor)-6}" font-size="11" fill="#8a6c31">Reserve + buffer ${t.floor}%</text><path d="M40,${y(settings.battery)} L${x(Math.min(t.km,t.rangeToEmpty))},${y(t.arrival)}" fill="none" stroke="#287cbb" stroke-width="3"/><text x="40" y="15" font-size="11">${settings.battery}% start</text><text x="40" y="145" font-size="11">0 km</text><text x="600" y="145" font-size="11">${t.km.toFixed(0)} km</text><text x="${Math.min(550,x(t.rangeToEmpty))}" y="${Math.max(15,y(t.arrival)-8)}" font-size="11">${t.arrival<0?'Battery empty':t.arrival.toFixed(0)+'% arrival'}</text></svg>`;
}

$('calculateTripTop').onclick=calculateLiveTrip;
